// HQ Kits proxy — forward only. NO CACHE, EVER.
//
// This is a DELIBERATELY SEPARATE workflow from hq-board, not a branch inside
// it. These endpoints WRITE inventory rows; the board's are open reads. Keeping
// them in different workflows makes that difference STRUCTURAL rather than a
// conditional somebody can get wrong later.
//
// ⚠ WHY NO CACHE HERE, when hq-board caches aggressively:
//   kitsCommit  — a write. Caching a write is nonsense.
//   kitsLookup  — a stock/shelf read whose whole job is to be current.
//   kitsQueue   — looks cacheable and ISN'T. It is the list of kits still
//                 awaiting a decision, and it changes the instant anyone
//                 expands one (here, from the sidebar, or via the modal).
//                 Serving a stale queue would show a picker a kit that no
//                 longer needs doing. The server re-derives at commit time so
//                 nothing would actually be written twice — it would fail
//                 loudly instead — but sending someone to a shelf for work
//                 that is already done is its own kind of wrong.
//
// Volume is a handful of calls per expansion session, not a 20s poll, so the
// Apps Script quota argument that justifies the board's cache does not apply.

const body = ($input.first().json.body) || {};

const EXEC_URL = '__APPS_SCRIPT_EXEC_URL__';
const TOKEN    = '__APP_SECRET_TOKEN__';

// The shared token proves the call came through this proxy. It does NOT say
// who is asking — every browser opening the page would present the same one.
// `initData` (Telegram's signed identity, forwarded untouched from the page)
// is what identifies the human, and Apps Script verifies its HMAC. We pass it
// straight through and never inspect it here.
let res;
try {
  res = await this.helpers.httpRequest({
    method:  'POST',
    url:     EXEC_URL,
    body:    Object.assign({}, body, { token: TOKEN }),
    json:    true,
    timeout: 60000
  });
} catch (err) {
  // Never throw: a thrown Code node returns no body, and the page would see a
  // dead socket instead of something it can show the picker.
  return [{ json: { ok: false, message: 'proxy: ' + (err.message || String(err)) } }];
}

return [{ json: res }];
